param([string]$OutputDirectory = "backups")
$ErrorActionPreference="Stop";$root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path;$target=[IO.Path]::GetFullPath((Join-Path $root $OutputDirectory));if(-not $target.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw "Backup path must be inside project root"};New-Item -ItemType Directory -Force $target|Out-Null;$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$file=Join-Path $target "krupim-d1-$stamp.sql";Write-Host "Exporting remote D1 read-only snapshot to $file";pnpm exec wrangler d1 export krupim-mathlearning --remote --output $file;if($LASTEXITCODE-ne 0-or-not(Test-Path $file)){throw "D1 export failed"};$hash=(Get-FileHash -Algorithm SHA256 $file).Hash;Set-Content -Encoding ascii "$file.sha256" "$hash  $([IO.Path]::GetFileName($file))";Write-Host "Backup complete. Verify and move it to encrypted off-site storage."
